void GPIO_Init(GPIO_Handle_t *h) {
    GPIO_PCLK_EN(h->pGPIOx);   // clock first
    h->pGPIOx->MODER &= ~(3u << (2 * h->Pin));
    h->pGPIOx->MODER |= (h->Mode << (2 * h->Pin));
}

